def count_numbers_with_power_of_two(n, e):
    power_of_two = str(2 ** e)
    length = len(power_of_two)

    # Initialize dp array
    dp = [[0] * (length + 1) for _ in range(length + 1)]
    dp[0][0] = 1

    for i in range(1, length + 1):
        dp[i][0] = dp[i - 1][0]
        for j in range(1, min(i, length) + 1):
            dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1]

    def atMostK(s, k):
        m = len(s)
        res = 0
        for i in range(m):
            d = int(s[i])
            for j in range(k, 0, -1):
                if d >= int(power_of_two[j - 1]):
                    res += dp[m - i - 1][j - 1]
                else:
                    break
            if d < int(power_of_two[k - 1]):
                res += dp[m - i - 1][k]
        return res

    return atMostK(str(n), length)

